/* Hardware events are only looked at at function entries and on backward branches (the interpreter's
 * "sync mode" uses exactly the same safe points, which is what makes lock-step verification possible). */
void rt_check(u32 pc);
int rt_entry(u32 pc);
#define CHECK_EVENT(pc) do { if (unlikely(cpu.cycles >= g_next_event || g_slow)) rt_check(pc); } while (0)
/* function entry: additionally bails out to the interpreter once recompiled code has been invalidated */
#define FUNC_ENTRY(pc) do { if (unlikely(cpu.cycles >= g_next_event || g_slow)) { if (rt_entry(pc)) return; } } while (0)

/* `jr ra`: return to the host caller. If the function was left through a modified ra, continue there. */
#define RET_TO(t) do { u32 _t = (t); if (unlikely(_t != ra0)) rt_ret_mismatch(_t, ra0); return; } while (0)
void rt_ret_mismatch(u32 target, u32 expected);

#endif
